UPDATE "Product" AS p SET
  "name" = CASE WHEN p."name" = c.old_name THEN c.new_name ELSE p."name" END,
  "brandId" = CASE WHEN current_brand."name" = c.old_brand THEN new_brand."id" ELSE p."brandId" END,
  "unit" = CASE WHEN p."unit" = c.old_unit THEN c.new_unit ELSE p."unit" END,
  "description" = CASE WHEN p."description" = c.old_description THEN c.new_description ELSE p."description" END,
  "updatedAt" = CURRENT_TIMESTAMP
FROM (VALUES
