) AS c(id, old_name, old_brand, old_unit, old_description, new_name, new_brand, new_unit, new_description)
JOIN "Brand" AS current_brand ON current_brand."name" = c.old_brand OR current_brand."name" = c.new_brand
JOIN "Brand" AS new_brand ON new_brand."name" = c.new_brand
WHERE p."id" = c.id AND p."brandId" = current_brand."id"
  AND p."name" IN (c.old_name, c.new_name)
  AND (p."name" <> c.new_name OR p."brandId" <> new_brand."id" OR p."unit" = c.old_unit OR p."description" = c.old_description);
